# END EMBEDDED 970 FIRMWARE


def require(ok, message):
    if not ok:
        raise RuntimeError(message)


def utc():
    return datetime.now(timezone.utc).isoformat()


def sha(data):
    return hashlib.sha256(data).hexdigest()


def durable(path, data):
    with path.open("xb") as stream:
        stream.write(data)
        stream.flush()
        os.fsync(stream.fileno())


def json_file(path, data):
    path.write_text(json.dumps(data, indent=2) + "\n", encoding="utf-8")


def checked_download(url, path, digest):
    if path.exists():
        data = path.read_bytes()
    else:
        print("Downloading " + path.name, flush=True)
        request = urllib.request.Request(url, headers={"User-Agent": "Nebular-437-debug/1"})
        with urllib.request.urlopen(request, timeout=60) as response:
            data = response.read(2 * 1024 * 1024 + 1)
        require(len(data) <= 2 * 1024 * 1024, "Unexpectedly large dependency")
        require(sha(data) == digest, "Download hash mismatch: " + path.name)
        durable(path, data)
    require(sha(data) == digest, "Cached dependency hash mismatch: " + path.name)
    return data


def load_tools(cache):
    cache.mkdir(parents=True, exist_ok=True)
    base = "https://raw.githubusercontent.com/gerard780/hanshow-rp2040-programmer/" + PROGRAMMER_COMMIT + "/"
    for relative, digest in DEPENDENCIES.items():
        checked_download(base + relative, cache / Path(relative).name, digest)
    sys.path.insert(0, str(cache.resolve()))
    import benchmark_readback as bench
    from write_validation import MeasuredFlash, ConservativeFlash
    spec = importlib.util.spec_from_file_location("nebular_sws_reader", cache / "TLSR825xComFlasher.py")
    reader = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(reader)
    return bench, MeasuredFlash, ConservativeFlash, reader


def get_firmware(version, supplied, cache, model="437", custom=None):
    require(model in MODELS, "Unknown model")
    if custom:
        # Own firmware (n970-fw): bypasses ONLY the pinned size/hash/CRC check of the experimental build.
        # Still required: TLNK header, length field equal to the file length, fits the application area.
        data = Path(custom).read_bytes()
        require(len(data) >= 0x28 and data[8:12] == b"KNLT" and struct.unpack_from("<I", data, 24)[0] == len(data),
                "Custom firmware: invalid TLNK header or length field")
        require(len(data) <= MODELS[model]["app_limit"] - SECTOR, "Custom firmware is too large for the application area")
        return data
    require(version in (FIRMWARE if model == "437" else ("1",)), "Unsupported model/build combination")
    size, digest = FIRMWARE[version] if model == "437" else FIRMWARE_970
    name = "EXPERIMENTAL_ATC_Nebular_" + model + "Q_N_v" + version + ".bin"
    if supplied:
        data = supplied.read_bytes()
    elif model == "970":
        data = zlib.decompress(base64.b85decode(EMBEDDED_970))
    else:
        cache.mkdir(parents=True, exist_ok=True)
        url = "https://raw.githubusercontent.com/gerard780/nebular-pro-qn-atc-oepl/" + FIRMWARE_COMMIT + "/firmware/" + name
        data = checked_download(url, cache / name, digest)
    require(len(data) == size and sha(data) == digest, "Firmware differs from the pinned v" + version + " build")
    require(data[8:12] == b"KNLT" and struct.unpack_from("<I", data, 24)[0] == size,
            "Invalid TLNK header or application length")
    require(struct.unpack_from("<I", data, size - 4)[0] == (zlib.crc32(data[:-4]) ^ 0xffffffff),
            "Invalid application CRC")
    return data


def plan(before, firmware, model="437"):
    profile = MODELS[model]
    require(len(before) == profile["flash_size"], "Incomplete full backup for model " + model)
    offset = profile["product_offset"]
    require(before[offset:offset + 92] == profile["product"],
            "Factory record does not match this " + model + "Q-N revision; no writes")
    padded = firmware + b"\xff" * (-len(firmware) % SECTOR)
    require(SECTOR <= len(padded) <= profile["app_limit"], "Application crosses " + hex(profile["app_limit"]))
    expected = padded + before[len(padded):]
    order = [offset for offset in list(range(SECTOR, len(padded), SECTOR)) + [0]
             if before[offset:offset + SECTOR] != expected[offset:offset + SECTOR]]
    return padded, expected, order


def role(port):
    text = " ".join(str(getattr(port, field, "") or "") for field in ("interface", "hwid", "device", "description"))
    if re.search(r"SWS|MI_00|if00|:1\.0(?:\b|$)", text, re.I):
        return "sws"
    if re.search(r"Tag UART|MI_02|if02|:1\.2(?:\b|$)", text, re.I):
        return "uart"
    return "unknown"


def port_rows(ports):
    return [dict(device=p.device, serial=p.serial_number, vid=p.vid, pid=p.pid,
                 description=p.description, interface=p.interface, hwid=p.hwid, role=role(p)) for p in ports]


def select_ports(ports, args):
    candidates = [p for p in ports if (p.vid, p.pid) == (0xcafe, 0x4012)
                  and (not args.bridge_serial or p.serial_number == args.bridge_serial)]
    serials = {p.serial_number for p in candidates}
    require(len(serials) == 1 and None not in serials, "Expected one Hanshow Zero; use --bridge-serial if several are connected")
    board = next(iter(serials))
    selected = []
    for desired, explicit in (("sws", args.flash_port), ("uart", args.uart_port)):
        matches = [p for p in candidates if p.device == explicit] if explicit else [p for p in candidates if role(p) == desired]
        require(len(matches) == 1, "Cannot identify " + desired + " port. Run --list-ports, then specify --flash-port and --uart-port")
        require(role(matches[0]) in (desired, "unknown"), "Selected port has the wrong interface role")
        selected.append(matches[0].device)
    require(selected[0] != selected[1], "SWS and UART must be separate ports")
    return board, selected[0], selected[1]


def usb_status(device):
    raw = bytes(device.ctrl_transfer(0xc0, 1, 0, 0, 40, timeout=2000))
    require(len(raw) == 40, "Incomplete programmer status")
    magic, version, flags, sws_baud, uart_baud, rx, tx, faults, uart_rx, uart_drops = struct.unpack("<10I", raw)
    require(magic == 0x31505348, "Unexpected programmer USB protocol")
    return dict(version=f"{version >> 16}.{version & 65535}", reset_enabled=bool(flags & 1),
                reset_asserted=bool(flags & 2), sws_open=bool(flags & 4), uart_open=bool(flags & 8),
                sws_baud=sws_baud, uart_baud=uart_baud, sws_rx=rx, sws_tx=tx,
                sws_faults=faults, uart_rx=uart_rx, uart_drops=uart_drops)


class Uart:
    def __init__(self, serial_module, port, baud, output, log):
        self.serial_module, self.port, self.baud, self.output, self.log = serial_module, port, baud, output, log
        self.stop = threading.Event()
        self.ready = threading.Event()
        self.error = None
        self.thread = threading.Thread(target=self.run, daemon=True)

    def start(self):
        self.thread.start()
        require(self.ready.wait(10), "UART did not open")
        self.check()

    def check(self):
        if self.error:
            raise RuntimeError("UART capture failed: " + self.error)

    def close(self):
        self.stop.set()
        self.thread.join(5)

    def run(self):
        try:
            port = self.serial_module.Serial(port=None, baudrate=self.baud, timeout=.1)
            port.dtr, port.rts = True, False
            port.port = self.port
            with port, (self.output / "uart.bin").open("xb") as raw, \
                    (self.output / "uart.txt").open("x", encoding="utf-8") as text, \
                    (self.output / "uart-timed.jsonl").open("x", encoding="utf-8") as timed:
                decoder = codecs.getincrementaldecoder("utf-8")("replace")
                started = time.monotonic()
                offset = 0
                self.log("uart_opened", port=self.port, baud=self.baud, receive_only=True)
                self.ready.set()
                while not self.stop.is_set():
                    data = port.read(4096)
                    if not data:
                        continue
                    decoded = decoder.decode(data)
                    raw.write(data)
                    text.write(decoded)
                    timed.write(json.dumps(dict(utc=utc(), elapsed=time.monotonic() - started,
                                                offset=offset, count=len(data), raw_hex=data.hex(), text=decoded)) + "\n")
                    raw.flush()
                    text.flush()
                    timed.flush()
                    if decoded:
                        self.log("uart_received", offset=offset, count=len(data), text=decoded)
                    offset += len(data)
                text.write(decoder.decode(b"", final=True))
                self.log("uart_finished", bytes=offset)
        except BaseException as error:
            self.error = f"{type(error).__name__}: {error}"
            self.ready.set()
            self.log("uart_failed", error=self.error)


def snapshot(flash, output, name, log, model="437"):
    flash_size = MODELS[model]["flash_size"]
    data = bytearray()
    with (output / name).open("xb") as stream:
        for offset in range(0, flash_size, SECTOR):
            sector = flash.read_sector(offset)
            require(len(sector) == SECTOR, "Short flash read")
            stream.write(sector)
            data.extend(sector)
            if len(data) % 65536 == 0:
                stream.flush()
                log("read_progress", file=name, bytes=len(data), total=flash_size)
        stream.flush()
        os.fsync(stream.fileno())
    log("snapshot_saved", file=name, sha256=sha(data), md5=hashlib.md5(data).hexdigest())
    return bytes(data)


def capture_failed_sector(flash, offset, expected, output, log, model="437"):
    """Preserve two bounded app-sector reads before rollback destroys evidence."""
    require(0 <= offset < MODELS[model]["app_limit"] and offset % SECTOR == 0, "Diagnostic read outside application")
    wanted = expected[offset:offset + SECTOR]
    reads = []
    for attempt in (1, 2):
        actual = flash.read_sector(offset)
        require(len(actual) == SECTOR, "Short failed-sector capture")
        name = f"failed-sector-{offset:05x}-read{attempt}.bin"
        durable(output / name, actual)
        mismatches = [(index, a, b) for index, (a, b) in enumerate(zip(wanted, actual)) if a != b]
        reads.append(dict(file=name, sha256=sha(actual), mismatch_bytes=len(mismatches),
                          unexpected_zero_bits=sum(bin(a & ~b).count("1") for _, a, b in mismatches),
                          unexpected_one_bits=sum(bin(b & ~a).count("1") for _, a, b in mismatches),
                          first_mismatches=[dict(address=hex(offset + i), expected=f"{a:02x}", actual=f"{b:02x}")
                                            for i, a, b in mismatches[:64]]))
    result = dict(offset=hex(offset), expected_sha256=sha(wanted), reads=reads,
                  two_reads_equal=reads[0]["sha256"] == reads[1]["sha256"])
    json_file(output / "failed-sector.json", result)
    log("failed_sector_captured", **result)


def install(flash, before, expected, order, output, log, halted, *, conservative=False, model="437"):
    """Whole-flash verified transaction; failure includes a partially written sector."""
    touched = []
    verified = True  # initially no flash mutation
    try:
        if order:
            verified = False
            flash.unlock()
            for offset in order:
                halted()
                flash.begin_measurement()
                touched.append(offset)
                writer = flash.rewrite_sector if conservative else flash.write_sector
                writer(offset, expected[offset:offset + SECTOR], expected_before=before[offset:offset + SECTOR])
                log("sector_verified", offset=hex(offset), completed=len(touched), total=len(order),
                    metrics=getattr(flash, "metrics", {}))
        after = snapshot(flash, output, "after.bin", log, model)
        require(after == expected, "Whole-flash readback differs from expected bytes")
        verified = True
        preserve = MODELS[model]["app_limit"]
        log("whole_flash_verified", sha256=sha(after), preserved_from=hex(preserve),
            factory_and_upper_flash_equal=after[preserve:] == before[preserve:])
        return dict(ok=True, image_verified=True, touched=touched)
    except BaseException as error:
        log("install_failed", error=f"{type(error).__name__}: {error}")
        if touched:
            try:
                capture_failed_sector(flash, touched[-1], expected, output, log, model)
            except BaseException as capture_error:
                log("failed_sector_capture_failed", error=f"{type(capture_error).__name__}: {capture_error}")
        # Existing transport handles conservative rollback at a slower baud.
        try:
            flash.prepare_recovery()
            recovery = flash.recovery()
            for offset in sorted(set(touched) - {0}) + ([0] if 0 in touched else []):
                halted()
                recovery.begin_measurement()
                recovery.rewrite_sector(offset, before[offset:offset + SECTOR], recovery.read_sector(offset))
                log("rollback_sector_verified", offset=hex(offset))
            restored = snapshot(recovery, output, "recovered.bin", log, model)
            require(restored == before, "Whole-flash rollback mismatch")
            verified = True
            log("rollback_verified", sha256=sha(restored))
        except BaseException as recovery_error:
            verified = False
            log("rollback_failed", error=f"{type(recovery_error).__name__}: {recovery_error}")
        return dict(ok=False, image_verified=verified, touched=touched, error=f"{type(error).__name__}: {error}")


def flash_970_class(base, bench, layout="auto"):
    """Model-scoped transport policy; never change the imported 437 backend globals.

    Telink SDK mid1460c8 (GD25LD80C): SR1, mask1c; mid011460c8
    (GD25LE/LQ80C): SR1+SR2, mask407c. JEDEC alone cannot distinguish them.
    """
    class Flash970(base):
        status_layout = layout

        def spi(self, command, count=0):
            command = bytes(command)
            require(command and 0 <= count <= SECTOR, "Invalid SPI request")
            opcode = command[0]
            if opcode in (3, 5, 0x35, 0x9f, 0x4b):
                if opcode == 3:
                    address = int.from_bytes(command[1:4], "big")
                    require(len(command) == 4 and address + count <= 0x100000, "Read outside 970 flash")
            else:
                require(self.allow_writes and opcode in (1, 2, 6, 0x20), "SPI mutation is disabled or unsupported")
                if opcode in (2, 0x20):
                    address = int.from_bytes(command[1:4], "big")
                    require(self.unlocked, "Unlocked session required")
                    if opcode == 0x20:
                        require(len(command) == 4 and address % SECTOR == 0 and address + SECTOR <= 0x30000,
                                "Erase outside 970 application")
                    else:
                        require(5 <= len(command) <= 260 and address + len(command) - 4 <= 0x30000
                                and (address % 256) + len(command) - 4 <= 256, "Program outside 970 application/page")
            started = time.monotonic()
            try:
                self.checked(0xb3, [0x80])
                self.checked(0x0d, [0])
                self.checked(0x0c, list(command) + ([0] if count else []))
                if count:
                    self.checked(0x0d, [0x0a])
                    return bench.block_read(self.reader, self.port, self.device, 0x0c, count)
                return b""
            finally:
                try:
                    self.checked(0x0d, [1])
                finally:
                    self.checked(0xb3, [0])
                if hasattr(self, "metrics") and opcode in (2, 6, 0x20):
                    key = {2: "program_seconds", 6: "write_enable_seconds", 0x20: "erase_seconds"}[opcode]
                    self.metrics[key] += time.monotonic() - started
                    if opcode != 6:
                        self.pending = key
                    if opcode == 0x20:
                        self.erase_address = int.from_bytes(command[1:4], "big")
                    if opcode == 2:
                        self.metrics["pages"] += 1
                        self.metrics["program_bytes"] += len(command) - 4

        def read_sector(self, offset):
            require(isinstance(offset, int) and offset >= 0 and offset % SECTOR == 0
                    and offset + SECTOR <= 0x100000, "Read outside 970 sector boundaries")
            started = time.monotonic()
            data = self.spi([3, offset >> 16, (offset >> 8) & 255, offset & 255], SECTOR)
            if hasattr(self, "metrics"):
                self.metrics["sector_reads_seconds"].append(time.monotonic() - started)
            return data

        def status(self):
            low = self.spi([5], 1)[0]
            return low if self.status_layout == "gd25ld8" else low | self.spi([0x35], 1)[0] << 8

        def select_status_layout(self):
            value = self.status()
            if self.status_layout == "auto":
                # A meaningful SR2 distinguishes the quad layout. A zero SR2
                # with protected SR1 does not distinguish an 8-bit part.
                require(value == 0 or (value & 0xff00 and not value & ~0x7a7c),
                        "Ambiguous c86014 protection layout: confirm --flash-status-layout gd25ld8 or gd25lq16; no writes")
                self.status_layout = "gd25lq16"
            allowed = 0x1c if self.status_layout == "gd25ld8" else 0x7a7c
            require(not value & ~allowed and value == self.status(), "Unknown or unstable c86014 protection status; no writes")
            return value

        def unlock(self):
            require(self.allow_writes and self.protection is None, "Explicit new write session required")
            value = self.select_status_layout()
            self.protection = value
            self._set_status(value & ~(0x1c if self.status_layout == "gd25ld8" else 0x407c))
            self.unlocked = True

        def _set_status(self, value):
            mask = 0x1c if self.status_layout == "gd25ld8" else 0x407c
            require(self.allow_writes and self.protection is not None
                    and value in (self.protection, self.protection & ~mask), "Status write changes non-protection bits")
            if self.status() != value:
                self.spi([6])
                command = [1, value & 255]
                if self.status_layout != "gd25ld8":
                    command.append(value >> 8)
                self.spi(command)
                self.ready()
                require(self.status() == value, "970 protection status did not verify")

        def program_sector(self, offset, data, expected_before, chunk):
            require(offset >= 0 and offset % SECTOR == 0 and offset + SECTOR <= 0x30000
                    and len(data) == SECTOR and len(expected_before) == SECTOR, "Sector outside 970 application")
            require(self.allow_writes and self.unlocked, "Unlocked write session required")
            require(self.read_sector(offset) == expected_before, "Live sector differs from same-tag backup")
            self.spi([6])
            self.spi([0x20, offset >> 16, (offset >> 8) & 255, offset & 255])
            self.ready()
            for start in range(0, SECTOR, chunk):
                part = data[start:start + chunk]
                if part != b"\xff" * chunk:
                    address = offset + start
                    self.spi([6])
                    self.spi([2, address >> 16, (address >> 8) & 255, address & 255] + list(part))
                    self.ready()
            require(self.read_sector(offset) == data, "970 programmed sector readback mismatch")

        def write_sector(self, offset, data, *, expected_before):
            self.program_sector(offset, data, expected_before, 256)

        def rewrite_sector(self, offset, data, expected_before):
            self.program_sector(offset, data, expected_before, 64)

    return Flash970


def run_flash(args, output, device, tools, firmware, log, uart):
    import serial
    bench, MeasuredFlash, ConservativeFlash, reader = tools
    model = getattr(args, "model", "437")
    profile = MODELS[model]
    if model == "970":
        layout = getattr(args, "flash_status_layout", "auto")
        MeasuredFlash = flash_970_class(MeasuredFlash, bench, layout)
        ConservativeFlash = flash_970_class(ConservativeFlash, bench, layout)
    bench.select_825x_width(device)
    result = dict(ok=False, cpu_reset_verified=False, image_verified=False, protection_verified=True)
    connection = serial.Serial(port=None, baudrate=args.baud, timeout=.1, write_timeout=3)
    connection.dtr, connection.rts = False, False
    connection.port = args.flash_port
    with connection as port:
        FlashClass = ConservativeFlash if args.write_mode == "conservative" else MeasuredFlash
        flash = FlashClass(reader, port, device, allow_writes=args.apply)

        def halted():
            require(bench.block_read(reader, port, device, 0x602, 1) == b"\x05", "CPU halt does not verify")

        def slow_transport():
            device.ctrl_transfer(0x40, 0x12, 0, 0, b"", timeout=2000)
            time.sleep(.06)
            port.reset_input_buffer()
            require(reader.rd_wr_usbcom_blk(port, reader.sws_code_end()), "Speed-change stop echo failed")
            port.baudrate = 921600
            require(reader.set_sws_speed(port, 24000000), "Slow speed calibration failed")
            halted()

        def prepare_recovery():
            slow_transport()
            require(flash.spi([0x4b, 0, 0, 0, 0], 16).hex() == result["flash_uid"], "Recovery target changed")

        def recovery():
            backend = ConservativeFlash(reader, port, device, allow_writes=True)
            if model == "970":
                backend.status_layout = flash.status_layout
            backend.unlocked = True
            return backend

        flash.prepare_recovery, flash.recovery = prepare_recovery, recovery
        try:
            reader.activate(port, 3000)
            require(reader.set_sws_auto_speed(port) and reader.set_sws_speed(port, 24000000), "SWS calibration failed")
            halted()
            require(reader.sws_read_data(port, 0x7d, 3) == [2, 0x62, 0x55], "Unsupported MCU")
            require(flash.spi([0x9f], 3) == bytes.fromhex(profile["jedec"]), "Flash does not match --model " + model)
            uid = flash.spi([0x4b, 0, 0, 0, 0], 16)
            require(uid not in (bytes(16), b"\xff" * 16) and uid == flash.spi([0x4b, 0, 0, 0, 0], 16), "Flash UID does not repeat")
            protection = flash.status()
            if model == "437":
                require(protection in (0x2c, 0x382c), "Unknown flash protection layout")
            result.update(model=model, flash_bytes=profile["flash_size"], chip_id="026255", jedec=profile["jedec"],
                          flash_uid=uid.hex(), protection_original=hex(protection))
            log("device_verified", **result)
            before = snapshot(flash, output, "before-1.bin", log, model)
            second = snapshot(flash, output, "before-2.bin", log, model)
            require(before == second, "The two full backups differ; writes refused")
            result["image_verified"] = True
            padded, expected, order = plan(before, firmware, model)
            durable(output / "recovery-application.bin", before[:len(padded)])
            durable(output / "application-padded.bin", padded)
            result.update(backup_sha256=sha(before), firmware_sha256=sha(firmware), firmware_md5=hashlib.md5(firmware).hexdigest(),
                          firmware_crc=hex(struct.unpack_from("<I", firmware, len(firmware) - 4)[0]),
                          firmware_bytes=len(firmware), write_bytes=len(padded), preserve_start=hex(len(padded)),
                          product_record=profile["product"].hex(), factory_tail_sha256=sha(before[profile["factory_start"]:]),
                          planned_sectors=[hex(x) for x in order])
            json_file(output / "identity.json", result)
            log("plan_verified", sectors=len(order), apply=args.apply, preserve_start=hex(len(padded)))
            if args.apply:
                if model == "970":
                    flash.select_status_layout()
                    result["flash_status_layout"] = flash.status_layout
                    log("flash_status_layout_verified", layout=flash.status_layout)
                uart.check()
                require(flash.spi([0x4b, 0, 0, 0, 0], 16) == uid, "Identity changed before unlock")
                if args.write_mode == "conservative":
                    slow_transport()
                result.update(write_mode=args.write_mode, write_baud=port.baudrate,
                              program_chunk_bytes=64 if args.write_mode == "conservative" else 256)
                log("write_transport_selected", mode=result["write_mode"], baud=result["write_baud"],
                    program_chunk_bytes=result["program_chunk_bytes"])
                # An unexpected exception (including failed journal I/O) must
                # never leave the pre-write verification authorizing a reset.
                result["image_verified"] = False
                result.update(install(flash, before, expected, order, output, log, halted,
                                      conservative=args.write_mode == "conservative", model=model))
            else:
                result["ok"] = True
                log("backup_only_no_flash_writes")
        except BaseException as error:
            result.update(ok=False, error=f"{type(error).__name__}: {error}")
            log("flash_session_failed", error=result["error"])
        finally:
            if flash.protection is not None:
                result["protection_verified"] = False
                try:
                    flash.restore_protection()
                    require(flash.status() == flash.protection, "Restored protection did not repeat")
                    result.update(protection_verified=True, protection_final=hex(flash.status()))
                    log("protection_restored", status=result["protection_final"])
                except BaseException as error:
                    result.update(ok=False, cleanup_error=str(error))
                    log("protection_restore_failed", error=str(error))
            try:
                device.ctrl_transfer(0x40, 0x12, 0, 0, b"", timeout=2000)
                time.sleep(.06)
                port.reset_input_buffer()
                require(reader.rd_wr_usbcom_blk(port, reader.sws_code_end()), "Stop echo failed")
                flash.checked(0x0d, [1])
                flash.checked(0xb3, [0])
                if result["image_verified"] and result["protection_verified"]:
                    uart.check()
                    log("cpu_reset_requested_uart_running")
                    flash.checked(0x6f, [0x22])
                    port.flush()
                    result["cpu_reset_verified"] = True
                    log("cpu_reset_verified")
                else:
                    log("cpu_kept_halted_for_recovery")
            except BaseException as error:
                result.update(ok=False, cleanup_error=str(error))
                log("cleanup_failed", error=str(error))
    return result


def summarize_uart(data):
    text = data.decode("utf-8", "replace")
    n970 = [line for line in text.splitlines() if "N970" in line]
    names = {0: "idle", 1: "reset_wait", 2: "sensor_wait", 3: "power_wait",
             4: "refresh_wait", 5: "off_wait", 6: "done", 7: "error"}
    stages = []
    for line in n970:
        match = re.search(r"N970 v1 (error )?state=(\d+) pass=(\d+) BUSY=(\d+)", line)
        if match:
            failed, state, component, busy = match.groups()
            stages.append(dict(state=int(state), stage=names.get(int(state), "unknown"),
                               pass_index=int(component), busy=int(busy), failed=bool(failed)))
    temperatures = [dict(temperature_c=int(t), raw=raw, band=int(band), pass_index=int(component))
                    for t, raw, band, component in re.findall(
                        r"N970 v1 panel=(-?\d+) raw=([0-9a-fA-F]{4}) band=(\d+) pass=(\d+)", text)]
    return dict(bytes=len(data), sha256=sha(data), utf8_replacements=text.count("\ufffd"),
                crc_headers=re.findall(r"Checking CRC in Header:\s*([0-9a-fA-F]+)", text),
                crc_successes=re.findall(r"CRC is Correct:\s*([0-9a-fA-F]+)", text),
                boot_banner_count=text.count("Checking TLNK Header:"),
                n437_lines=[line for line in text.splitlines() if "N437" in line],
                n970_lines=n970, n970_stages=stages, n970_panel_temperatures=temperatures,
                n970_errors=[line for line in n970 if re.search(r"error|reject|refused|skipped", line)],
                last_lines=text.splitlines()[-30:],
                note="Repeated banners suggest resets. Neither a verified write nor a UART completion proves a visible display update.")


def share_bundle(output):
    # Explicit allowlist: never include full dumps, recovery images, or firmware.
    names = ["report.json", "events.jsonl", "uart.bin", "uart.txt", "uart-timed.jsonl", "observations.txt", "failed-sector.json"]
    names += [p.name for p in output.glob("failed-sector-*-read*.bin")
              if re.fullmatch(r"failed-sector-[012][0-9a-f]{4}-read[12]\.bin", p.name)]
    path = output / "debug-share.zip"
    with zipfile.ZipFile(path, "x", compression=zipfile.ZIP_DEFLATED) as archive:
        for name in names:
            if (output / name).exists():
                archive.write(output / name, name)
    return path


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--apply", action="store_true", help="Install the selected application; otherwise back up only")
    parser.add_argument("--monitor-only", action="store_true", help="Capture UART without SWire/reset/flash operations")
    parser.add_argument("--list-ports", action="store_true")
    parser.add_argument("--model", choices=tuple(MODELS), default="437", help="Target model: 437 (default) or 970")
    parser.add_argument("--version", choices=("1", "3", "4", "5"), help="Build: defaults to 437 v5 or 970 v1")
    parser.add_argument("--flash-status-layout", choices=("auto", "gd25ld8", "gd25lq16"), default="auto",
                        help="970: confirm 8-bit GD25LD or 16-bit GD25LE/LQ when auto reports ambiguity")
    parser.add_argument("--firmware", type=Path, help="Optional local bin; must match the selected pinned build")
    parser.add_argument("--custom-firmware", type=Path, help="Own firmware bin (KNLT header + length field are checked, the pinned hash/CRC are NOT)")
    parser.add_argument("--extract-firmware", type=Path, help="Save selected verified binary and exit without accessing hardware")
    parser.add_argument("--flash-port", help="SWS interface, e.g. COM5 or /dev/ttyACM0")
    parser.add_argument("--uart-port", help="Tag UART interface, e.g. COM6 or /dev/ttyACM1")
    parser.add_argument("--bridge-serial")
    parser.add_argument("--baud", type=int, choices=(921600, 1500000, 2000000), default=2000000)
    parser.add_argument("--write-mode", choices=("conservative", "fast"), default="conservative",
                        help="Default conservative: 64-byte programs at 921600, matching the successful rollback path")
    parser.add_argument("--uart-baud", type=int, default=115200, help="Use the rate that gave your readable ATC log")
    parser.add_argument("--seconds", type=int, help="UART collection after verified reset: 437 defaults to 300s, 970 to 600s")
    parser.add_argument("--output", type=Path)
    parser.add_argument("--cache", type=Path, default=Path("nebular-debug-cache"))
    parser.add_argument("--no-questions", action="store_true", help="Skip recording manual BLE/OEPL/display observations")
    args = parser.parse_args()
    args.version = args.version or MODELS[args.model]["default_version"]
    args.seconds = args.seconds if args.seconds is not None else (600 if args.model == "970" else 300)
    if args.version not in (FIRMWARE if args.model == "437" else ("1",)):
        parser.error("Model 437 supports v3/v4/v5; model 970 supports v1")
    if args.extract_firmware:
        if args.apply or args.monitor_only or args.list_ports:
            parser.error("--extract-firmware cannot be combined with hardware modes")
        data = get_firmware(args.version, args.firmware, args.cache, args.model, args.custom_firmware)
        durable(args.extract_firmware, data)
        print(json.dumps(dict(file=str(args.extract_firmware.resolve()), bytes=len(data), sha256=sha(data))))
        return 0
    if args.monitor_only and args.apply:
        parser.error("--monitor-only cannot be combined with --apply")
    if not 1 <= args.seconds <= 1800 or args.uart_baud <= 0:
        parser.error("--seconds must be 1..1800 and --uart-baud positive")
    try:
        import serial
        from serial.tools import list_ports
    except ImportError:
        raise SystemExit("Install dependencies: python -m pip install pyserial pyusb libusb-package")
    ports = list(list_ports.comports())
    if args.list_ports:
        print(json.dumps(port_rows(ports), indent=2))
        return 0
    output = args.output or Path("nebular-debug-" + datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ"))
    output.mkdir(parents=True, exist_ok=False)
    lock = threading.Lock()

    def log(event, **details):
        row = dict(utc=utc(), event=event, **details)
        with lock:
            with (output / "events.jsonl").open("a", encoding="utf-8") as stream:
                stream.write(json.dumps(row) + "\n")
                stream.flush()
                os.fsync(stream.fileno())
            print(json.dumps(row), flush=True)

    result = dict(script_version=3, started_utc=utc(), os=platform.platform(), python=sys.version,
                  apply=args.apply, monitor_only=args.monitor_only, selected_firmware=args.version,
                  model=args.model, flash_status_layout=args.flash_status_layout,
                  ports=port_rows(ports), seconds=args.seconds, uart_baud=args.uart_baud,
                  programmer_commit=PROGRAMMER_COMMIT,
                  firmware_commit=FIRMWARE_COMMIT if args.model == "437" else None,
                  firmware_source="embedded local 970 v1" if args.model == "970" else "pinned GitHub build", ok=False)
    result["packages"] = {}
    for name in ("pyserial", "pyusb", "libusb-package"):
        try:
            result["packages"][name] = importlib.metadata.version(name)
        except importlib.metadata.PackageNotFoundError:
            result["packages"][name] = None
    uart, device = None, None
    exit_code = 1
    try:
        if args.monitor_only:
            require(args.uart_port, "--monitor-only needs --uart-port from --list-ports")
        else:
            board, args.flash_port, args.uart_port = select_ports(ports, args)
            result.update(bridge_serial=board, flash_port=args.flash_port, uart_port=args.uart_port)
            import usb.core
            import usb.backend.libusb1
            try:
                import libusb_package
                backend = usb.backend.libusb1.get_backend(find_library=libusb_package.find_library)
            except ImportError:
                backend = usb.backend.libusb1.get_backend()
            require(backend is not None, "No libusb backend. Install libusb-package; see README for Windows USB setup")
            devices = [d for d in usb.core.find(find_all=True, idVendor=0xcafe, idProduct=0x4012, backend=backend)
                       if d.serial_number == board]
            require(len(devices) == 1, "USB device does not match selected serial ports")
            device = devices[0]
            result["bridge_before"] = usb_status(device)
            require(result["bridge_before"]["version"] in ("1.4", "1.5", "1.6"), "Requires Hanshow programmer firmware v1.4-v1.6")
            require(result["bridge_before"]["reset_enabled"], "Programmer firmware must have tag reset enabled")
            tools = load_tools(args.cache)
            firmware = get_firmware(args.version, args.firmware, args.cache, args.model, args.custom_firmware)
        uart = Uart(serial, args.uart_port, args.uart_baud, output, log)
        uart.start()
        if not args.monitor_only:
            result["flash"] = run_flash(args, output, device, tools, firmware, log, uart)
            require(result["flash"]["ok"] and result["flash"]["cpu_reset_verified"],
                    "Flash session failed; see report and keep the backup directory")
        log("monitor_started", seconds=args.seconds)
        print("Watching UART. Check BLE discovery, OEPL discovery, and the screen now. Keep the programmer connected.", flush=True)
        deadline = time.monotonic() + args.seconds
        next_heartbeat = time.monotonic() + 15
        while time.monotonic() < deadline:
            uart.check()
            time.sleep(min(.25, max(0, deadline - time.monotonic())))
            if time.monotonic() >= next_heartbeat:
                log("monitor_progress", remaining_seconds=max(0, int(deadline - time.monotonic())),
                    uart_bytes=(output / "uart.bin").stat().st_size)
                next_heartbeat += 15
        if not args.no_questions and sys.stdin.isatty():
            print("Capture continues while you enter observations. Unknown is a useful answer.", flush=True)
            observations = {}
            for question in ("BLE visible/name?", "OEPL visible/type?", "Screen changed/what is shown?", "Power source/voltage and wiring notes?"):
                observations[question] = input(question + " ")
            json_file(output / "observations.txt", observations)
        result["ok"] = True
        exit_code = 0
    except BaseException as error:
        result["error"] = f"{type(error).__name__}: {error}"
        result["traceback"] = traceback.format_exc()
        log("run_failed", error=result["error"])
    finally:
        if uart:
            uart.close()
            if uart.error:
                result.update(ok=False, uart_error=uart.error)
                exit_code = 1
        if device:
            try:
                result["bridge_after"] = usb_status(device)
                first, last = result["bridge_before"], result["bridge_after"]
                result["new_sws_faults"] = (last["sws_faults"] - first["sws_faults"]) & 0xffffffff
                result["new_uart_drops"] = (last["uart_drops"] - first["uart_drops"]) & 0xffffffff
                if result["new_sws_faults"] or result["new_uart_drops"] or last["reset_asserted"]:
                    result["ok"], exit_code = False, 1
            except BaseException as error:
                result.update(ok=False, bridge_status_error=str(error))
                exit_code = 1
        if (output / "uart.bin").exists():
            result["uart_summary"] = summarize_uart((output / "uart.bin").read_bytes())
        result["finished_utc"] = utc()
        json_file(output / "report.json", result)
        bundle = share_bundle(output)
        print("Send back: " + str(bundle.resolve()), flush=True)
        print("Keep the full backup directory: " + str(output.resolve()), flush=True)
    return exit_code


if __name__ == "__main__":
    raise SystemExit(main())
